insert into public.flashcards (id, aula_id, ordem, frente, verso) values
  ('pass-a2-f01', 'pass-a2', 1, 'Qual é a grande pergunta da tabela 2 por 2 de diagnóstico?', 'O teste classifica corretamente quem tem e quem não tem a doença? Medidas: sensibilidade, especificidade, valores preditivos e acurácia.'),
  ('pass-a2-f02', 'pass-a2', 2, 'Qual a diferença entre a tabela 2 por 2 de diagnóstico e a de exposição e desfecho?', 'Diagnóstico: o teste acerta quem tem e quem não tem a doença? Exposição e desfecho: a exposição aumenta ou reduz o desfecho? (risco relativo, razão de chances, redução de risco absoluto).'),
  ('pass-a2-f03', 'pass-a2', 3, 'Qual é a regra de montagem da tabela 2 por 2 de diagnóstico?', 'Coluna é a verdade (com ou sem a doença, pelo enunciado ou padrão ouro); linha é o resultado do teste (positivo ou negativo).'),
  ('pass-a2-f04', 'pass-a2', 4, 'O que é cada casa da tabela: A, B, C e D?', 'A: verdadeiro positivo. B: falso positivo. C: falso negativo. D: verdadeiro negativo. A e D são acertos; B e C, erros.'),
  ('pass-a2-f05', 'pass-a2', 5, 'O que é falso positivo e qual o outro nome dele?', 'Teste positivo em quem não tem a doença (B); também chamado erro tipo 1. Ex.: teste de gravidez positivo no seu Antônio.'),
  ('pass-a2-f06', 'pass-a2', 6, 'O que é falso negativo?', 'Teste negativo em quem tem a doença (C). Ex.: dizer que uma gestante não está grávida. Na estatística, corresponde ao erro tipo 2.'),
  ('pass-a2-f07', 'pass-a2', 7, 'Nos nomes "falso positivo" e "verdadeiro negativo", positivo e negativo se referem a quê?', 'Ao resultado do teste, não à doença. E o resultado não muda a verdade: quem não tem a doença continua na coluna dos sem doença, mesmo com teste positivo.'),
  ('pass-a2-f08', 'pass-a2', 8, 'Se o teste serve para descobrir a doença, de onde sai a coluna da verdade?', 'Na prova, do enunciado. Na vida real, do padrão ouro (biópsia, cultura, diagnóstico confirmado). Ex.: no câncer de pulmão, a biópsia é a verdade e a tomografia é o teste avaliado.'),
  ('pass-a2-f09', 'pass-a2', 9, '"20 pessoas têm a doença": esse número vai em qual casa da tabela?', 'Em nenhuma: é o total da coluna dos doentes. Ainda não foi cruzado com o resultado do teste. Desenhe sempre uma linha e uma coluna de total.'),
  ('pass-a2-f10', 'pass-a2', 10, 'Quais os 4 passos para montar a tabela 2 por 2 a partir de um enunciado?', '1) Totais vão para fora. 2) Cruze coluna com linha. 3) Exclua o que não pode ser. 4) O resto sai por diferença.'),
  ('pass-a2-f11', 'pass-a2', 11, 'Hanseníase: 100 pessoas, 20 com e 80 sem a doença. Dos 20, 18 testaram positivo; dos 80, 52 testaram negativo. Monte a tabela.', 'A = 18, B = 28, C = 2, D = 52. Linhas: 46 positivos e 54 negativos.'),
  ('pass-a2-f12', 'pass-a2', 12, 'O júri: 10 réus, 3 assassinos. O júri condenou 6, dos quais 2 eram assassinos. Como fica a tabela?', 'A = 2 (assassinos condenados), B = 4 (inocentes presos), C = 1 (assassino solto), D = 3 (inocentes absolvidos). O júri acertou metade dos julgamentos.'),
  ('pass-a2-f13', 'pass-a2', 13, 'No desenho das bolinhas, o que é o retângulo, o círculo e a bolinha cheia?', 'Retângulo: a verdade. Círculo: o teste (dentro = testou positivo). Bolinha cheia: tem a doença; vazia: não tem.'),
  ('pass-a2-f14', 'pass-a2', 14, '⭐ [PROVA] O que é sensibilidade e qual a fórmula?', 'Capacidade do teste de encontrar os doentes. Olha a coluna dos doentes: A ÷ (A + C), ou verdadeiros positivos ÷ todos os doentes.'),
  ('pass-a2-f15', 'pass-a2', 15, 'Qual a sensibilidade do teste de hanseníase (A = 18, C = 2)?', '18 ÷ 20 = 90%: a cada 10 doentes, o teste encontra 9.'),
  ('pass-a2-f16', 'pass-a2', 16, 'Teste muito sensível: o que significa o resultado positivo e o negativo?', 'Negativo exclui a doença (quase não há falsos negativos). Positivo não confirma: pode ser falso positivo, precisa de outro teste.'),
  ('pass-a2-f17', 'pass-a2', 17, '⭐ [PROVA] Qual a armadilha clássica sobre o teste sensível?', 'Achar que, por pegar todos os doentes, o positivo confirma. É o oposto: o teste sensível serve para excluir quando dá negativo.'),
  ('pass-a2-f18', 'pass-a2', 18, 'Para que serve um teste muito sensível?', 'Rastreamento e triagem: não perder nenhum caso de doença grave (câncer, tromboembolismo pulmonar, aids). Melhor um falso positivo confirmado depois do que um doente sem tratamento.'),
  ('pass-a2-f19', 'pass-a2', 19, 'Cite exemplos de testes muito sensíveis do dia a dia.', 'Teste rápido para HIV, teste urinário de gravidez, Gram da secreção uretral (gonorreia no homem sintomático), troponina sensível e dímero D. 90% de sensibilidade já é muito sensível.'),
  ('pass-a2-f20', 'pass-a2', 20, 'Qual a sensibilidade do teste rápido para HIV e como interpretar o resultado?', '99,7 a 99,9%, fora da janela imunológica. Negativo: fica tranquilo. Positivo: preocupação média, precisa de confirmação.'),
  ('pass-a2-f21', 'pass-a2', 21, 'Como interpretar a troponina ultrassensível na suspeita de infarto?', 'É o primeiro exame: não pode deixar passar nenhum infarto. Negativa descarta; positiva sozinha não confirma (pode subir, por exemplo, na insuficiência cardíaca).'),
  ('pass-a2-f22', 'pass-a2', 22, 'Como interpretar o dímero D no tromboembolismo pulmonar?', 'Exame sensível, usado na baixa probabilidade. Negativo exclui. Positivo (mesmo muito alto) não confirma: a suspeita continua.'),
  ('pass-a2-f23', 'pass-a2', 23, 'Qual a diferença entre precisão e acurácia?', 'Acurácia: o quanto o teste acerta a verdade. Precisão: o quanto ele repete o mesmo resultado quando refeito. (Complemento, fora da aula.)'),
  ('pass-a2-f24', 'pass-a2', 24, '⭐ [PROVA] O que é especificidade e qual a fórmula?', 'Capacidade do teste de dar negativo para quem não tem a doença. Olha a coluna dos não doentes: D ÷ (B + D).'),
  ('pass-a2-f25', 'pass-a2', 25, 'Qual a especificidade do teste de hanseníase (B = 28, D = 52)?', '52 ÷ 80 = 65%.'),
  ('pass-a2-f26', 'pass-a2', 26, 'Teste muito específico: o que significa o resultado positivo e o negativo?', 'Positivo confirma (nenhum não doente testa positivo). Negativo não descarta: alguns doentes também testam negativo. Não serve para triar.'),
  ('pass-a2-f27', 'pass-a2', 27, 'Cite exemplos de testes muito específicos.', 'Biópsia (positiva para câncer confirma; negativa não descarta), ultrassom mostrando o bebê e angiotomografia de tórax para tromboembolismo. Sensíveis e específicos ao mesmo tempo são raros (citados: teste para HIV e Gram para gonorreia).'),
  ('pass-a2-f28', 'pass-a2', 28, 'Exame para tromboembolismo em 300 pacientes: A = 56, B = 5, C = 24, D = 215. Sensibilidade e especificidade?', 'Sensibilidade 70% (56 ÷ 80); especificidade 97,7% (215 ÷ 220). Pouco sensível e muito específico: não pode ser o dímero D. Se der positivo, confirma.'),
  ('pass-a2-f29', 'pass-a2', 29, '⭐ [PROVA] Qual a frase para "guardar, tirar foto, tirar print"?', 'Teste sensível negativo exclui. Teste específico positivo confirma.'),
  ('pass-a2-f30', 'pass-a2', 30, 'Sensibilidade alta, dita de três jeitos:', 'Muitos doentes testam positivo. Poucos doentes testam negativo. Poucos falsos negativos.'),
  ('pass-a2-f31', 'pass-a2', 31, 'Especificidade alta, dita de três jeitos:', 'Muitos não doentes testam negativo. Poucos não doentes testam positivo. Poucos falsos positivos.'),
  ('pass-a2-f32', 'pass-a2', 32, 'Por que, na prática, se faz um exame depois do outro?', 'Poucos testes são sensíveis e específicos ao mesmo tempo. Usa-se um sensível para excluir (dímero D) e um específico para confirmar (angiotomografia, biópsia).'),
  ('pass-a2-f33', 'pass-a2', 33, 'Suspeita de tromboembolismo pulmonar: como o escore de Wells muda o primeiro exame?', 'Probabilidade baixa: começa pelo dímero D (sensível). Probabilidade alta: vai direto para a angiotomografia, para confirmar.'),
  ('pass-a2-f34', 'pass-a2', 34, 'Ultrassom com Doppler negativo descarta tromboembolismo pulmonar?', 'Não: é um exame específico; positivo confirmaria, negativo não exclui. Doppler negativo + angiotomografia negativa (ou cintilografia negativa) descartam.'),
  ('pass-a2-f35', 'pass-a2', 35, 'Teste de hanseníase com sensibilidade 90% e especificidade 65%: serve para triagem ou diagnóstico?', 'Triagem. Poucos falsos negativos (só 2): o negativo exclui. O positivo tem 18 doentes e 28 não doentes: não serve para confirmar.'),
  ('pass-a2-f36', 'pass-a2', 36, 'Qual o método do Dr. Felipe para questões conceituais de sensibilidade e especificidade?', '1) Escolha o lado: sensibilidade só olha a coluna dos doentes (A e C); especificidade, a dos não doentes (B e D). 2) Extrapole: alta vira 100%, baixa vira 0%.'),
  ('pass-a2-f37', 'pass-a2', 37, 'Um teste com alta sensibilidade gera poucos falsos positivos?', 'Não dá para dizer: falso positivo está do lado dos não doentes, que a sensibilidade ignora. O certo é: encontra a maioria dos doentes.'),
  ('pass-a2-f38', 'pass-a2', 38, 'Qual o problema de um teste com baixa especificidade?', 'Muitos falsos positivos. Extrapolando para 0%: em 50 sem a doença, nenhum verdadeiro negativo e 50 falsos positivos.'),
  ('pass-a2-f39', 'pass-a2', 39, 'Influenza: 300 pacientes; 120 com a doença (96 testaram positivo) e 180 sem (144 negativos). Sensibilidade e especificidade?', 'A = 96, B = 36, C = 24, D = 144. Sensibilidade 96 ÷ 120 = 80%; especificidade 144 ÷ 180 = 80%. Sensibilidade e especificidade podem ser iguais.'),
  ('pass-a2-f40', 'pass-a2', 40, 'No exercício da influenza, os 120 com a doença são "os positivos"?', 'Não: são todos os doentes (verdadeiros positivos + falsos negativos). Os 24 do C também têm a doença, só testaram negativo.'),
  ('pass-a2-f41', 'pass-a2', 41, 'O que é acurácia e qual a fórmula?', 'Quanto o teste acerta no geral: (A + D) ÷ todos os resultados. Olha todo mundo.'),
  ('pass-a2-f42', 'pass-a2', 42, 'Qual a acurácia do teste de hanseníase (A = 18, D = 52, total 100)?', '(18 + 52) ÷ 100 = 70%.'),
  ('pass-a2-f43', 'pass-a2', 43, 'Que pergunta o valor preditivo positivo responde e qual a fórmula?', 'O teste deu positivo: qual a chance de o paciente realmente ter a doença? A ÷ (A + B), olhando a linha dos positivos.'),
  ('pass-a2-f44', 'pass-a2', 44, 'Que pergunta o valor preditivo negativo responde e qual a fórmula?', 'O teste deu negativo: qual a chance de o paciente realmente não ter a doença? D ÷ (C + D), olhando a linha dos negativos.'),
  ('pass-a2-f45', 'pass-a2', 45, '⭐ [PROVA] Sensibilidade e especificidade olham colunas ou linhas? E os valores preditivos?', 'Sensibilidade e especificidade: colunas (a verdade). Valores preditivos: linhas (o resultado do teste), que é o que o médico tem na mão.'),
  ('pass-a2-f46', 'pass-a2', 46, 'Hanseníase (A = 18, B = 28, C = 2, D = 52): valor preditivo positivo e negativo?', 'Positivo: 18 ÷ 46 = 39% (menos da metade dos positivos tem a doença, não confirma). Negativo: 52 ÷ 54 = 96% (exclui a doença).'),
  ('pass-a2-f47', 'pass-a2', 47, 'Erro comum: calcular o valor preditivo negativo da hanseníase como 52 ÷ 80. Por que está errado?', '52 ÷ 80 usa a coluna dos não doentes: isso é especificidade. No valor preditivo, olhe só a linha: 52 ÷ (52 + 2) = 52 ÷ 54.'),
  ('pass-a2-f48', 'pass-a2', 48, '⭐ [PROVA] O médico precisa calcular valor preditivo na prática? O que importa?', 'Não. Importa interpretar o resultado: o valor preditivo positivo nunca é 100%, então haverá positivos em quem não tem a doença. Interpretar valor preditivo cai na prova.'),
  ('pass-a2-f49', 'pass-a2', 49, 'Qual a diferença entre incidência e prevalência?', 'Incidência: casos novos num período (a torneira do balde). Prevalência: casos existentes num momento (a água acumulada).'),
  ('pass-a2-f50', 'pass-a2', 50, '⭐ [PROVA] A prevalência muda a sensibilidade e a especificidade?', 'Não: são características do exame. O que muda com a prevalência são os valores preditivos.'),
  ('pass-a2-f51', 'pass-a2', 51, '⭐ [PROVA] Qual a regra prática do efeito da prevalência nos valores preditivos?', 'O valor preditivo positivo segue a prevalência; o negativo vai ao contrário. Prevalência alta: positivo sobe, negativo cai.'),
  ('pass-a2-f52', 'pass-a2', 52, 'Teste com sensibilidade 90% e especificidade 90%, em 100 pacientes com prevalência de 10%. Monte a tabela e calcule os valores preditivos.', '10 doentes e 90 não doentes. A = 9, C = 1, D = 81, B = 9. Valor preditivo positivo 9 ÷ 18 = 50%; negativo 81 ÷ 82 = 99%.'),
  ('pass-a2-f53', 'pass-a2', 53, 'O mesmo teste (90% e 90%) no ambulatório de hanseníase, com prevalência de 80%. Qual o valor preditivo positivo?', '80 doentes e 20 não doentes: A = 72, C = 8, D = 18, B = 2. Valor preditivo positivo 72 ÷ 74 = 97% (era 50% com prevalência de 10%). Negativo: 18 ÷ 26 = 69%.'),
  ('pass-a2-f54', 'pass-a2', 54, 'Por que, com prevalência baixa, o valor preditivo positivo despenca?', 'Há muitos não doentes, e a pequena proporção de erro da especificidade (10% de 90 = 9 falsos positivos) se iguala aos verdadeiros positivos (9).'),
  ('pass-a2-f55', 'pass-a2', 55, '1.000 pessoas, prevalência de 1%, sensibilidade 90%, especificidade 65%. Monte a tabela e calcule os valores preditivos.', '10 doentes e 990 não doentes. A = 9, C = 1, D = 644, B = 346. Valor preditivo positivo 9 ÷ 355 = 2,5% (0,025 é 2,5%, não 0,025%); negativo 644 ÷ 645 = 99,8%.'),
  ('pass-a2-f56', 'pass-a2', 56, 'O mesmo teste (90% e 65%) em 1.000 pessoas com prevalência de 20%: valores preditivos?', '200 doentes e 800 não doentes. A = 180, C = 20, D = 520, B = 280. Positivo 180 ÷ 460 = 39%; negativo 520 ÷ 540 = 96%. O positivo subiu bastante e o negativo caiu um pouco.'),
  ('pass-a2-f57', 'pass-a2', 57, '⭐ [PROVA] Questão do exame nacional: triagem para hanseníase com sensibilidade 92%, especificidade 65% e prevalência baixa. Qual a afirmação correta?', 'O número de falsos positivos será elevado, devido à baixa especificidade e à baixa prevalência. Errado dizer que quase todos os positivos são verdadeiros pela alta sensibilidade: isso é valor preditivo positivo, que depende da prevalência.'),
  ('pass-a2-f58', 'pass-a2', 58, 'Como desenhar uma questão de prevalência que não dá números?', 'Invente uma população grande (1.000), leve "prevalência baixa" ao extremo (1% = 10 doentes) e arredonde (sensibilidade 92% vira 90%). Visualizar resolve a questão.')
